  93: { text: 'مقصودها الدلالة على آخر الليل بأن أتقى الأتقياء… في عين الرضا دائما، لا ينفك عنه في الدنيا والآخرة', src: { book: 'nazm', vol: 22, page: 100, sh: 11392 } },
