  100: { text: 'مقصودها الإعلام بأن أكثر الخلق يوم الزلزلة هالك لإيثار الفاني من العز والمال على الباقي عند ذي الجلال', src: { book: 'nazm', vol: 22, page: 210, sh: 11511 } },
  101: { text: 'مقصودها إيضاح يوم الدين بتصوير ثواني أحواله في مبدئه ومآله، وتقسيم الناس فيه إلى ناج وهالك', src: { book: 'nazm', vol: 22, page: 220, sh: 11522 } },
